import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

fun <T, R> List<T>.mapChecked15300(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
sealed class Outcome15301 {
    data class Success(val payload: String) : Outcome15301()
    data object Failure : Outcome15301()
}

fun describe15301(outcome: Outcome15301): String = when (outcome) {
    is Outcome15301.Success -> outcome.payload
    Outcome15301.Failure -> "failed"
}
class Counter15302 {
    var current: Int by Delegates.observable(24) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
